const { getMyOrder } = '../../Services/ApiUserService.jsx'
import React, { useEffect, useState, useMemo } from "react";
import { Button, Spinner } from "react-bootstrap";






const MyOrder = () => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);


    useEffect(() => {
        const fetchOrders = async () => {
            setLoading(true);
            setError(null);
            try {
                const data = await getMyOrder();
                setOrders(data || []);
            } catch (error) {
                setError("Failed to fetch orders");
            } finally {
                setLoading(false);
            }
        }
        fetchOrders();
    }, []);
    if (loading) {
        return (
            <div className="d-flex align-items-center gap-2">
                <Spinner animation="border" size="sm" />
                <span>Đang tải đơn hàng…</span>
            </div>
        );
    }
    if (error) {
        return (
            <div className="container py-4">
                <div className="alert alert-danger" role="alert">
                    <h4 className="alert-heading">Lỗi!</h4>
                    <p>{error}</p>
                    <button
                        className="btn btn-outline-danger"
                        onClick={() => window.location.reload()}
                    >
                        Thử lại
                    </button>
                </div>
            </div>
        );
    }
    if (!orders) {
        return (
            <div className="container py-4">
                <div className="alert alert-warning" role="alert">
                    Không tìm thấy đơn hàng nào.
                </div>
            </div>
        );
    }



    return (
        <div className="my-order-page">
            {/* Header + notice */}
            <p className="lead fst-italic mb-2">Kính gửi Quý khách hàng,</p>
            <p className="text-secondary mb-4">
                Để duy trì hiệu suất và bảo mật hệ thống, chúng tôi sẽ tiến hành
                <span className="fw-semibold text-danger"> xóa các dữ liệu đã lưu trữ quá 1 tháng</span>.
                Để tránh mất mát dữ liệu quan trọng, chúng tôi khuyến nghị Quý khách thực hiện
                sao lưu dữ liệu của mình ngay bây giờ.
            </p>

            {/* States */}
            {loading && (
                <div className="d-flex align-items-center gap-2">
                    <Spinner animation="border" size="sm" />
                    <span>Đang tải đơn hàng…</span>
                </div>
            )}

            {error && !loading && <div className="alert alert-danger">{error}</div>}

            {!loading && !error && (
                <div className="text-muted">Chưa có đơn hàng nào.</div>
            )}

            {/* Table */}
            {!loading && !error && (
                <div className="order-table-wrapper">
                    <table className="table align-middle order-table">
                        <thead>
                            <tr>
                                <th scope="col" className="text-uppercase small fw-bold text-secondary">ĐƠN HÀNG</th>
                                <th scope="col" className="text-uppercase small fw-bold text-secondary">NGÀY</th>
                                <th scope="col" className="text-uppercase small fw-bold text-secondary">TÌNH TRẠNG</th>
                                <th scope="col" className="text-uppercase small fw-bold text-secondary">TỔNG</th>
                                <th scope="col" className="text-uppercase small fw-bold text-secondary text-end">CÁC THAO TÁC</th>
                            </tr>
                        </thead>
                        <tbody>
                            {orders.map((o) => {
                                const id = o.order_id;
                                const date = fmtDate(o.time);
                                const qty = Number(o.quantity) || 0;
                                const money = fmtMoney(o.total_amount);
                                const stt = statusLabel(o.status);
                                return (
                                    <tr key={id}>
                                        <td className="fw-semibold">#{id}</td>
                                        <td>{date}</td>
                                        <td className="text-secondary">{stt}</td>
                                        <td>
                                            <span className="fw-bold">{money}</span>{" "}
                                            <span className="text-secondary small">cho {qty} mục</span>
                                        </td>
                                        <td className="text-end">
                                            <Button
                                                variant="warning"
                                                className="px-3 fw-bold text-white btn-view"
                                                onClick={() => onViewOrder?.(id)}
                                            >
                                                XEM
                                            </Button>
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
            )}
        </div>
    );
}

export default MyOrder;
